package org.icu.sepsis.deterioration;
import java.time.*;import java.util.*;import java.util.stream.Collectors;
import org.icu.sepsis.domain.Domain.*;import org.icu.sepsis.config.RuleConfig;import org.icu.sepsis.integration.ClinicalDataProvider;import org.springframework.stereotype.Service;
/** Source quality, not a clinical risk score. Never changes observations or screening rules. */
@Service public class DataQualityService {
 private final ClinicalDataProvider data;private final RuleConfig rules;
 public DataQualityService(ClinicalDataProvider data,RuleConfig rules){this.data=data;this.rules=rules;}
 private static final String[] CODES={"MAP_IBP","MAP_NIBP","MAP","HR","RR","TEMP","SPO2","GCS","LACTATE","CREA","URINE_OUTPUT","WEIGHT"};
 public Map<String,Object> read(Patient p,Instant now){try{return evaluate(p,now,data.observations(p.id,p.encounterId,now.minus(Duration.ofDays(7)),now),true,rules);}catch(RuntimeException failed){return evaluate(p,now,List.of(),false,rules);}}
 static int age(String code,RuleConfig cfg){return code.equals("LACTATE")?cfg.getLabFreshMinutes():code.equals("CREA")?1440:code.equals("WEIGHT")?10080:code.equals("URINE_OUTPUT")?60:cfg.getFreshMinutes();}
 static String label(String code){return Map.ofEntries(Map.entry("MAP_IBP","有创平均压"),Map.entry("MAP_NIBP","无创平均压"),Map.entry("MAP","平均动脉压"),Map.entry("HR","心率"),Map.entry("RR","呼吸频率"),Map.entry("TEMP","体温"),Map.entry("SPO2","血氧饱和度"),Map.entry("GCS","意识评分"),Map.entry("LACTATE","乳酸"),Map.entry("CREA","肌酐"),Map.entry("URINE_OUTPUT","逐小时尿量"),Map.entry("WEIGHT","体重")).getOrDefault(code,code);}
 static boolean unit(Observation o){String u=o.unit==null?"":o.unit;switch(o.parameterCode){case "HR":return u.equals("bpm");case "RR":return u.equals("/min");case "SPO2":return u.equals("%");case "TEMP":return Set.of("°C","C","℃").contains(u);case "GCS":return u.equals("score");case "LACTATE":return u.equals("mmol/L");case "CREA":return Set.of("μmol/L","µmol/L","umol/L").contains(u);case "URINE_OUTPUT":return u.equalsIgnoreCase("ml");case "WEIGHT":return u.equalsIgnoreCase("kg");default:return u.equals("mmHg");}}
 static String invalid(Observation o,Instant now,int age){if(o.eventTime==null)return "观察时间缺失";if(o.eventTime.isAfter(now)||o.ingestTime!=null&&o.ingestTime.isAfter(now))return "时间晚于评估时点";if("unconfirmed".equals(o.encounterLinkStatus))return "本次住院归属待核对";if("context_only".equals(o.clinicalUse))return "仅作背景报告，未参与当前判断";if(o.value==null||!Double.isFinite(o.value))return "数值缺失或无效";double v=o.value;boolean range=o.parameterCode.equals("HR")?v>=10&&v<=300:o.parameterCode.equals("RR")?v>=1&&v<=100:o.parameterCode.equals("TEMP")?v>=30&&v<=45:o.parameterCode.equals("SPO2")?v>=0&&v<=100:o.parameterCode.equals("GCS")?v>=3&&v<=15&&v==Math.rint(v):o.parameterCode.equals("LACTATE")?v>=0&&v<=40:o.parameterCode.equals("WEIGHT")?v>0&&v<=500:o.parameterCode.equals("CREA")||o.parameterCode.equals("URINE_OUTPUT")?v>=0:v>=10&&v<=300;if(!range)return "数值超出检查范围";if(!unit(o))return "单位缺失或不匹配";if(!"valid".equals(o.qualityStatus))return "来源有效性待核对";if(o.eventTime.isBefore(now.minus(Duration.ofMinutes(age))))return "超过本观察项的数据检查窗口";return "";}
 public static Map<String,Object> evaluate(Patient p,Instant now,List<Observation> rows,boolean available,RuleConfig cfg){var scoped=rows.stream().filter(o->Objects.equals(p.id,o.patientId)&&Objects.equals(p.encounterId,o.encounterId)&&Objects.equals(p.department,o.department)).collect(Collectors.toList());var items=new ArrayList<Map<String,Object>>();var counts=new LinkedHashMap<String,Integer>();for(String key:List.of("ready","review","stale","missing","unavailable"))counts.put(key,0);
 for(String code:CODES){if(code.equals("MAP")&&scoped.stream().anyMatch(o->Set.of("MAP_IBP","MAP_NIBP").contains(o.parameterCode)))continue;var selected=scoped.stream().filter(o->code.equals(o.parameterCode)).collect(Collectors.toList());var latest=selected.stream().filter(o->o.eventTime!=null).max(Comparator.comparing(o->o.eventTime)).orElse(selected.isEmpty()?null:selected.get(0));String reason=!available?"来源读取失败":latest==null?"近7天未取得记录":invalid(latest,now,age(code,cfg));boolean conflict=latest!=null&&latest.eventTime!=null&&selected.stream().anyMatch(o->latest.eventTime.equals(o.eventTime)&&(!Objects.equals(latest.value,o.value)||!Objects.equals(latest.unit,o.unit)));if(conflict)reason="最新时点的数值或单位冲突";String status=!available?"unavailable":latest==null?"missing":reason.isEmpty()?"ready":reason.startsWith("超过")?"stale":"review";counts.put(status,counts.get(status)+1);var item=new LinkedHashMap<String,Object>();item.put("code",code);item.put("label",label(code));item.put("status",status);item.put("reason",reason);item.put("time",latest==null?null:latest.eventTime);item.put("value",latest==null?null:latest.value);item.put("unit",latest==null?null:latest.unit);item.put("source",latest==null?null:latest.sourceSystem);item.put("sourceRecordId",latest==null?null:latest.sourceRecordId);item.put("freshMinutes",age(code,cfg));item.put("records",selected.size());item.put("ageMinutes",latest==null||latest.eventTime==null?null:Duration.between(latest.eventTime,now).toMinutes());var bins=new ArrayList<String>();for(int i=0;i<24;i++){Instant end=now.minus(Duration.ofHours(23-i)),start=end.minus(Duration.ofHours(1));var in=selected.stream().filter(o->o.eventTime!=null&&o.eventTime.isAfter(start)&&!o.eventTime.isAfter(end)).collect(Collectors.toList());boolean clash=in.stream().anyMatch(a->in.stream().anyMatch(b->a.eventTime.equals(b.eventTime)&&(!Objects.equals(a.value,b.value)||!Objects.equals(a.unit,b.unit))));bins.add(!available?"unavailable":in.isEmpty()?"missing":clash?"review":in.stream().anyMatch(o->invalid(o,end,age(code,cfg)).isEmpty())?"ready":"review");}item.put("hours",bins);items.add(item);}
 var out=new LinkedHashMap<String,Object>();out.put("schemaVersion",1);out.put("patientId",p.id);out.put("encounterId",p.encounterId);out.put("asOf",now);out.put("available",available);out.put("counts",counts);out.put("items",items);out.put("truncated",rows.size()>=2000);out.put("scope","数据质量检查，不是风险分层；体温MEWS可使用独立4小时窗口，其他专项按各自依据窗口。");return out;}
}
